#if 0
"""
#endif
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define BASE 1000000000U

typedef struct {
    uint32_t *v;
    size_t len;
    size_t cap;
} Big;

static void die(void) {
    exit(1);
}

static void big_ensure(Big *x, size_t need) {
    if (x->cap >= need) {
        return;
    }
    size_t new_cap = x->cap ? x->cap : 1;
    while (new_cap < need) {
        new_cap *= 2;
    }
    uint32_t *nv = (uint32_t *)realloc(x->v, new_cap * sizeof(uint32_t));
    if (!nv) {
        die();
    }
    x->v = nv;
    x->cap = new_cap;
}

static void big_init(Big *x, uint32_t value) {
    x->v = NULL;
    x->len = 1;
    x->cap = 0;
    big_ensure(x, 1);
    x->v[0] = value;
}

static void big_add(Big *out, const Big *a, const Big *b) {
    size_t n = a->len > b->len ? a->len : b->len;
    big_ensure(out, n + 1);

    uint64_t carry = 0;
    for (size_t i = 0; i < n; ++i) {
        uint64_t s = carry;
        if (i < a->len) {
            s += a->v[i];
        }
        if (i < b->len) {
            s += b->v[i];
        }
        out->v[i] = (uint32_t)(s % BASE);
        carry = s / BASE;
    }

    out->len = n;
    if (carry) {
        out->v[out->len++] = (uint32_t)carry;
    }
}

static void big_print(const Big *x) {
    printf("%u", x->v[x->len - 1]);
    for (size_t i = x->len - 1; i-- > 0;) {
        printf("%09u", x->v[i]);
    }
    putchar(10);
}

static void big_free(Big *x) {
    free(x->v);
    x->v = NULL;
    x->len = 0;
    x->cap = 0;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        return 1;
    }
    if (argv[1][0] == '-') {
        return 1;
    }

    errno = 0;
    char *end = NULL;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (errno != 0 || !end || *end != 0) {
        return 1;
    }

    Big a;
    Big b;
    Big c;
    big_init(&a, 0);
    big_init(&b, 1);
    big_init(&c, 0);

    for (unsigned long long i = 0; i < n; ++i) {
        big_add(&c, &a, &b);
        Big t = a;
        a = b;
        b = c;
        c = t;
    }

    big_print(&a);

    big_free(&a);
    big_free(&b);
    big_free(&c);
    return 0;
}
